package dev.bugcapsule.android.core

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * `conformance/interactions.json` (generated by the Dart reference): typed
 * values, interaction keys, payload encoding with the default redactor and
 * delivery scheduling, every section and case.
 */
@Suppress("UNCHECKED_CAST")
class InteractionConformanceTest {
    private val doc = SpecFixtures.json("conformance/interactions.json")
    private fun section(name: String) = doc[name] as List<Map<String, Any?>>

    @Test
    fun typedValues() {
        val cases = section("typedValues")
        assertTrue(cases.size >= 15)
        for (c in cases) {
            val name = c["name"] as String
            assertEquals(name, c["reencoded"], TypedValue.encode(TypedValue.decode(c["encoded"])))
            assertEquals(name, c["canonical"], Json.canonical(c["encoded"]))
            assertEquals(name, c["hash"], RequestKeyBuilder.hash(Json.canonical(c["encoded"])))
        }
    }

    @Test
    fun kotlinValuesEncodeLikeDart() {
        assertEquals(mapOf("\$t" to "int", "v" to "9007199254740993"), TypedValue.encode(9007199254740993L))
        assertEquals(9007199254740991L, TypedValue.encode(9007199254740991L))
        assertEquals(mapOf("\$t" to "double", "v" to "80.0"), TypedValue.encode(80.0))
        assertEquals(mapOf("\$t" to "double", "v" to "NaN"), TypedValue.encode(Double.NaN))
        assertEquals(mapOf("\$t" to "double", "v" to "-0.0"), TypedValue.encode(-0.0))
        assertEquals(mapOf("\$t" to "double", "v" to "-Infinity"), TypedValue.encode(Double.NEGATIVE_INFINITY))
        assertEquals(12.5, TypedValue.encode(12.5))
        assertEquals(mapOf("\$t" to "bytes", "b64" to "AAEC/w=="), TypedValue.encode(byteArrayOf(0, 1, 2, -1)))
        assertEquals(mapOf("\$t" to "i32", "v" to listOf(1L, -2L, 3L)), TypedValue.encode(intArrayOf(1, -2, 3)))
        assertEquals(mapOf("\$t" to "i64", "v" to listOf("1", "-9223372036854775808")), TypedValue.encode(longArrayOf(1, Long.MIN_VALUE)))
        assertEquals(mapOf("\$t" to "f64", "v" to listOf(1.5, "Infinity")), TypedValue.encode(doubleArrayOf(1.5, Double.POSITIVE_INFINITY)))
        assertEquals(mapOf("\$t" to "f32", "v" to listOf(0.5, "NaN")), TypedValue.encode(floatArrayOf(0.5f, Float.NaN)))
        assertEquals(
            mapOf("\$t" to "map", "e" to listOf(listOf(1L, "one"), listOf("two", 2L))),
            TypedValue.encode(linkedMapOf<Any, Any>(1 to "one", "two" to 2)),
        )
        assertEquals(mapOf("\$t" to "map", "e" to listOf(listOf("\$t", "x"))), TypedValue.encode(mapOf("\$t" to "x")))
        assertEquals("unsupported", (TypedValue.encode(Any()) as Map<*, *>)["\$t"])
        assertTrue(!TypedValue.isReplayable(TypedValue.encode(listOf(Any()))))

        // Decoding restores the Kotlin types.
        val bytes = TypedValue.decode(mapOf("\$t" to "bytes", "b64" to "AAEC/w==")) as ByteArray
        assertTrue(bytes.contentEquals(byteArrayOf(0, 1, 2, -1)))
        assertTrue((TypedValue.decode(mapOf("\$t" to "i64", "v" to listOf("1", "-9223372036854775808"))) as LongArray).contentEquals(longArrayOf(1, Long.MIN_VALUE)))
        assertEquals(80.0, TypedValue.decode(mapOf("\$t" to "double", "v" to "80.0")))
        assertTrue((TypedValue.decode(mapOf("\$t" to "double", "v" to "-0.0")) as Double).let { it == 0.0 && 1 / it < 0 })
        assertEquals(mapOf(1L to "one"), TypedValue.decode(mapOf("\$t" to "map", "e" to listOf(listOf(1L, "one")))))
        assertEquals(9007199254740993L, TypedValue.decode(mapOf("\$t" to "int", "v" to "9007199254740993")))
        for (n in 0..7) {
            val b = ByteArray(n) { (it * 37 - 5).toByte() }
            assertTrue(Base64.decode(Base64.encode(b)).contentEquals(b))
        }
    }

    @Test
    fun keys() {
        for (c in section("keys")) {
            assertEquals(c["key"], interactionKey(c["scope"] as String, c["method"] as String?, c["args"]))
        }
    }

    @Test
    fun payloads() {
        val redactor = Redactor()
        val cases = section("payloads")
        assertTrue(cases.size >= 7)
        for (c in cases) {
            val encoder = PayloadEncoder(
                redactor = { redactor },
                budget = PayloadBudget(InteractionLimits(maxPayloadBytes = J.int(c["maxPayloadBytes"]) ?: 64 * 1024)),
                stats = DependencyStats(),
                now = { 0L },
                captureBinary = c["captureBinary"] as Boolean? ?: false,
                redactedReplayable = c["redactedReplayable"] as Boolean? ?: false,
            )
            val payload = encoder.encode(TypedValue.decode(c["value"]), c["kind"] as String?)
            assertEquals(c["name"] as String, c["payload"], payload.toJson())
        }
    }

    @Test
    fun schedules() {
        val cases = section("schedules")
        assertTrue(cases.size >= 5)
        for (c in cases) assertSchedule(c)
    }

    /** Port of `_schedule` in `tool/generate_conformance.dart`. */
    private fun assertSchedule(c: Map<String, Any?>) {
        val name = c["name"] as String
        var seq = 0L
        val events = (c["events"] as List<Map<String, Any?>>).map {
            CapsuleEvent(++seq, J.long(it["t"])!!, it["type"] as String, it["data"] as Map<String, Any?>)
        }
        var now = 0L
        val deliveries = ArrayList<Map<String, Any?>>()
        val script = InteractionScript(events, (c["deps"] as List<String>).toSet(), { now }, J.long(c["base"])!!)
        val deliver = InteractionHandler { r -> deliveries.add(mapOf("seq" to r.event.seq, "at" to now)) }
        fun advanceTo(target: Long) {
            while (true) {
                val next = script.nextDueAt ?: break
                if (next > target) break
                if (next > now) now = next
                script.pump()
            }
            now = target
            script.pump()
        }
        val matched = ArrayList<Long?>()
        for (step in c["steps"] as List<Map<String, Any?>>) {
            advanceTo(J.long(step["at"])!!)
            when (step["op"]) {
                "runStarted" -> script.runStarted(now)
                "bind" -> script.bind(step["scope"] as String, deliver)
                "unbind" -> script.unbind(step["scope"] as String)
                "take" -> matched.add(script.take(step["dep"] as String, step["type"] as String, step["key"] as String)?.event?.seq)
                "takeNext" -> matched.add(script.takeNext(step["scope"] as String, (step["types"] as List<String>).toSet())?.event?.seq)
            }
            script.pump()
        }
        while (true) advanceTo(script.nextDueAt ?: break)
        val unused = script.unused(J.long(c["failureT"])).map { (type, detail) -> mapOf("type" to type, "detail" to detail) }
        assertEquals("$name: matched", (c["matched"] as List<Any?>).map { J.long(it) }, matched)
        assertEquals("$name: deliveries", c["deliveries"], deliveries)
        assertEquals("$name: unused", c["unused"], unused)
        assertEquals("$name: events", c["events"], events.map { it.toJson() })
    }
}
